 P.ensurePlanningModel(App.state);P.ensureEnterpriseModel(App.state);const b=(App.state.bookings||[]).slice().sort((a,b)=>new Date(a.start)-new Date(b.start)),care=(App.state.resourceCareBookings||[]).filter(x=>x.status==='Scheduled'),planned=new Set(b.map(x=>x.requestId)),open=App.state.requests.filter(r=>!['DELIVERED','CLOSED','RELEASED'].includes(r.status)),view=App.filters.planView||'portfolio',weeks=Number(App.filters.planWeeks||8),includePotential=App.filters.planPotential!==false,selected=App.filters.planBuild||open[0]?.id||null,structuralGaps=open.filter(r=>r.triage?.planQuality==='Structural gap').length,late=open.filter(r=>r.triage?.slackDays<0).length,provisional=open.filter(r=>r.triage?.planQuality&&r.triage.planQuality!=='Best feasible').length;
