function renderEquipmentMaster(){P.ensureEnterpriseModel(App.state);const today=P.todayISO(),careWeeks=Number(App.filters.careWeeks||26),due=App.state.equipment.filter(e=>(e.calibrationDue&&P.daysBetween(today,e.calibrationDue)<=30)||(e.maintenanceDue&&P.daysBetween(today,e.maintenanceDue)<=30)),trainingDue=(App.state.trainingCertificates||[]).filter(c=>c.status==='Valid'&&c.expiresAt&&P.daysBetween(today,c.expiresAt)<=60),care=new P.ResourceCareService().forecast(App.state,careWeeks);return pageHeader('Equipment, Calibration, Maintenance & Training','One readiness engine coordinates equipment calibration, preventive maintenance and training renewals against committed bookings and probability-weighted future demand.')+`<div class="grid cols-4">${metric('Equipment',App.state.equipment.length)+metric('Equipment due ≤30 d',due.length)+metric('Training due ≤60 d',trainingDue.length)+metric('Scheduled readiness slots',(App.state.resourceCareBookings||[]).filter(x=>x.status==='Scheduled').length)}</div><div style="height:14px"></div><div class="card"><div class="section-title-row"><div><span class="eyebrow">OPTIMIZED READINESS PLAN</span><h2>Calibration, maintenance & training schedule</h2><div class="subtle">The optimizer searches exact conflict-free working slots before each due date, then scores them against committed work and probability-weighted future demand. Scheduled slots become real planner constraints, so AUTO-PLAN works around them.</div></div><label class="compact-select">Horizon<select id="careWeeks">${[13,26,52].map(n=>`<option value="${n}" ${careWeeks===n?'selected':''}>${n} weeks</option>`).join('')}</select></label></div>${carePlanTable(care)}</div><div style="height:14px"></div><div class="grid cols-2">${App.state.equipment.map(e=>{const certs=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===e.id).sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt))),latest=certs[0];return `<div class="card"><div class="section-title-row"><div><span class="pill">${esc(e.id)}</span><h3>${esc(e.name)}</h3></div>${status(P.equipmentReady(e)?'Ready':'Attention')}</div><div class="score-row"><span>Capability</span><strong>${esc(e.capability)}</strong></div><div class="score-row"><span>Calibration</span><strong>${esc(e.calibrationStatus)} · due ${P.formatDate(e.calibrationDue)}</strong></div><div class="score-row"><span>Latest certificate</span><strong>${latest?`${esc(latest.certificateNo)} · ${P.formatDate(latest.completedAt)}`:'No certificate'}</strong></div><div class="score-row"><span>Maintenance</span><strong>${esc(e.maintenanceStatus)} · due ${P.formatDate(e.maintenanceDue)}</strong></div><div class="score-row"><span>Equipment rate</span><strong>${P.currency(e.hourlyCost)} / h</strong></div><div class="route-toolbar equipment-actions">${btn('Certificates',`data-view-cal-certificates="${e.id}"`,'button tiny secondary')}${can('calibration:manage')||currentRole()==='administrator'?btn('Record calibration',`data-record-calibration="${e.id}"`,'button tiny primary'):''}${can('maintenance:manage')||currentRole()==='administrator'?btn('Record maintenance',`data-record-maintenance="${e.id}"`,'button tiny secondary'):''}${can('finance:manage')||currentRole()==='administrator'?btn('Edit rate',`data-edit-equipment-rate="${e.id}"`,'button tiny secondary'):''}</div></div>`}).join('')}</div>`}
